        private void Trace(string phase, int repeat, int tick)
        {
            int start = phase == "move" ? 1170 : phase == "contact" ? 2310 : -1;
            if (start < 0 || tick < start || tick > start + 90) return;
            Assert.That(manager.lodCenter.position, Is.EqualTo(fixedLodPosition));
            if (traceWriter == null) traceWriter = new BinaryWriter(new GZipStream(File.Create(Path.Combine(output, variant + "-" + phase + "-r" + repeat + ".trace.gz")), CompressionLevel.Optimal));
            var b = manager.Buffers; b.agentBuffer.GetData(agents); b.combatBuffers.hpReadBuffer.GetData(hp);
            if (congestion == null || congestion.Length != b.combatBuffers.engagementSlotAssignmentBuffer.count) congestion = new int[b.combatBuffers.engagementSlotAssignmentBuffer.count];
            b.combatBuffers.engagementSlotAssignmentBuffer.GetData(congestion);
            traceWriter.Write(tick);
            for (int i = 0; i < agents.Length; i++)
            {
                var agent = agents[i]; int c = agents.Length + i * 12;
                traceWriter.Write(agent.position.x); traceWriter.Write(agent.position.z); traceWriter.Write(agent.velocity.x); traceWriter.Write(agent.velocity.z);
                traceWriter.Write((float)hp[i]); traceWriter.Write((float)agent.currentState); traceWriter.Write(Bits(congestion[c+5])); traceWriter.Write(Bits(congestion[c+4]));
                traceWriter.Write(Bits(congestion[c+2])); traceWriter.Write(Bits(congestion[c+3])); traceWriter.Write(Bits(congestion[c])); traceWriter.Write(Bits(congestion[c+1]));
            }
            if (tick == start + 90) { traceWriter.Dispose(); traceWriter = null; }
        }
        private IEnumerator Observe(string phase, int repeat, int[] ticks, Vector3 goal)
        {
            int last = 0;
            foreach (int tick in ticks)
            {
                for (int frame = last; frame < tick; frame++)
                {
                    yield return null;
                    Trace(phase, repeat, frame + 1);
                    if (!manager.IsBattleRunning) { Read(phase + "-ended", repeat, frame + 1, goal, false); yield break; }
                }
                Read(phase, repeat, tick, goal, repeat == 0 && (phase == "move" && tick == 1800 || phase == "contact" && tick == 2400)); last = tick;
            }
        }
